/**
 * Icon markup. Decorative by default (aria-hidden); pass a label to expose it.
 *
 * @param string $name  Icon name.
 * @param string $class Extra class.
 * @param string $label Accessible label.
 * @return string
 */
function a2e_icon( $name, $class = '', $label = '' ) {
	$icons  = a2e_icon_paths();
	$glyphs = a2e_glyph_paths();
	$aria   = $label ? ' role="img" aria-label="' . esc_attr( $label ) . '"' : ' aria-hidden="true" focusable="false"';
	$cls    = 'icon icon--' . sanitize_html_class( $name ) . ( $class ? ' ' . esc_attr( $class ) : '' );
	if ( isset( $glyphs[ $name ] ) ) {
		return '<svg class="' . $cls . '" viewBox="0 0 24 24" fill="currentColor"' . $aria . '><path d="' . $glyphs[ $name ] . '"/></svg>';
	}
	if ( ! isset( $icons[ $name ] ) ) {
		$name = 'sparkle';
	}
	return '<svg class="' . $cls . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"' . $aria . '>' . $icons[ $name ] . '</svg>';
}

/**
 * Echo an icon.
 *
 * @param string $name  Icon name.
 * @param string $class Extra class.
 */
function a2e_the_icon( $name, $class = '' ) {
	echo a2e_icon( $name, $class ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
}
